begin;
select no_plan();
select ok((select not enabled from private.reaper_pending_containment_policy), 'new policy is disabled');
select ok((select bool_and(relrowsecurity) from pg_class where oid in ('private.reaper_pending_containment_policy'::regclass,'private.reaper_pending_containment_runs'::regclass)), 'both private tables enable RLS');
select ok(not has_table_privilege('anon','private.reaper_pending_containment_runs','select') and not has_table_privilege('authenticated','private.reaper_pending_containment_runs','update'), 'browser roles cannot read or mutate requests');
select ok(not has_table_privilege('service_role','private.reaper_pending_containment_runs','delete'), 'receipts cannot be deleted by runtime');
select ok(has_table_privilege('service_role','private.reaper_pending_containment_runs','select,insert,update'), 'runtime has explicit narrow table grants');
select ok(not has_function_privilege('anon',oid,'execute') and not has_function_privilege('authenticated',oid,'execute') and has_function_privilege('service_role',oid,'execute') and not prosecdef and proconfig @> array['search_path=""'], 'RPC is service-only invoker with empty search path: ' || proname)
  from pg_proc where proname in ('reaper_reserve_pending_containment','reaper_pending_containment_status','reaper_begin_pending_containment_write','reaper_finish_pending_containment','reaper_set_pending_containment_enabled');
select ok(exists(select 1 from pg_index where indexrelid='private.reaper_pending_containment_one_active_guild_idx'::regclass and indisunique and indpred is not null), 'all active states have one guild writer');
set local role service_role;
select is(public.reaper_reserve_pending_containment('gateway:11111111-1111-4111-8111-111111111111','11111111111111111',repeat('a',64),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'disabled','disabled default has no acquisition');
select is((select count(*) from private.reaper_pending_containment_runs),0::bigint,'disabled creates no dedup row');
select is(public.reaper_pending_containment_status('gateway:11111111-1111-4111-8111-111111111111'),'{"state":"missing","result":null}'::jsonb,'status missing is read only');
select is(public.reaper_set_pending_containment_enabled(true),true,'explicit service activation');
select is(public.reaper_reserve_pending_containment('gateway:11111111-1111-4111-8111-111111111111','11111111111111111',repeat('a',64),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'acquired','Gateway reserves');
select is(public.reaper_reserve_pending_containment('gateway:11111111-1111-4111-8111-111111111111','11111111111111111',repeat('a',64),'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),'duplicate','same UUID never gets second owner');
select is(public.reaper_reserve_pending_containment('gateway:11111111-1111-4111-8111-111111111111','22222222222222222',repeat('a',64),'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),'identity_conflict','same UUID bound to member');
select is(public.reaper_reserve_pending_containment('gateway:11111111-1111-4111-8111-111111111111','11111111111111111',repeat('b',64),'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),'identity_conflict','same UUID bound to input');
select is(public.reaper_reserve_pending_containment('discord:22222222222222222','*',repeat('b',64),'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),'busy','bulk slash shares guild fence');
select is(public.reaper_reserve_pending_containment('rollback:22222222-2222-4222-8222-222222222222','*',repeat('b',64),'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),'busy','rollback shares guild fence');
select is((select count(*) from private.reaper_pending_containment_runs),1::bigint,'busy attempts consume no request identity');
select throws_ok($$select public.reaper_set_pending_containment_enabled(true)$$,'55000','Reconcile active containment before changing policy.','cannot re-enable over active fence');
select is(public.reaper_begin_pending_containment_write('gateway:11111111-1111-4111-8111-111111111111','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),false,'wrong owner cannot write');
select is(public.reaper_finish_pending_containment('gateway:11111111-1111-4111-8111-111111111111','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','rejected'),false,'wrong owner cannot finish');
select is(public.reaper_begin_pending_containment_write('gateway:11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),true,'owner begins before writes');
select is(public.reaper_begin_pending_containment_write('gateway:11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),true,'same owner fences each write');
select is(public.reaper_finish_pending_containment('gateway:11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','rejected'),false,'writing cannot claim no writes');
select throws_ok($$select public.reaper_finish_pending_containment('gateway:11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','completed','{"discordWrites":1,"dbWrites":2,"staleRecordsCleared":0,"extra":1}')$$,'22023','Invalid containment receipt.','reject extra receipt fields');
select throws_ok($$select public.reaper_finish_pending_containment('gateway:11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','completed','{"discordWrites":10001,"dbWrites":2,"staleRecordsCleared":0}')$$,'22023','Invalid containment receipt.','receipt bounded');
select throws_ok($$select public.reaper_finish_pending_containment('gateway:11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','completed','{"discordWrites":-1,"dbWrites":2,"staleRecordsCleared":0}')$$,'22023','Invalid containment receipt.','receipt cannot be negative');
select throws_ok($$select public.reaper_finish_pending_containment('gateway:11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','completed','{"discordWrites":1.1,"dbWrites":2,"staleRecordsCleared":0}')$$,'22023','Invalid containment receipt.','receipt integer only');
select is(public.reaper_finish_pending_containment('gateway:11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','completed','{"discordWrites":1,"dbWrites":2,"staleRecordsCleared":0}'),true,'completion stores bounded receipt');
select is(public.reaper_pending_containment_status('gateway:11111111-1111-4111-8111-111111111111'),'{"state":"completed","result":{"discordWrites":1,"dbWrites":2,"staleRecordsCleared":0}}'::jsonb,'lost acknowledgment resolved by permanent receipt');
select is(public.reaper_begin_pending_containment_write('gateway:11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),false,'completed cannot write');
select is(public.reaper_finish_pending_containment('gateway:11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','blocked'),false,'lost finish ack cannot downgrade completion');
select is(public.reaper_reserve_pending_containment('gateway:11111111-1111-4111-8111-111111111111','11111111111111111',repeat('a',64),'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),'duplicate','completed dedup forever');
select is(public.reaper_reserve_pending_containment('discord:22222222222222222','*',repeat('b',64),'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),'acquired','bulk apply can acquire after completion');
select is(public.reaper_finish_pending_containment('discord:22222222222222222','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','rejected'),true,'known prewrite rejection terminal');
select is(public.reaper_reserve_pending_containment('discord:22222222222222222','*',repeat('b',64),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'duplicate','rejected requests never reopen');
select is(public.reaper_reserve_pending_containment('rollback:22222222-2222-4222-8222-222222222222','*',repeat('b',64),'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),'acquired','rollback acquires same fence');
select is(public.reaper_begin_pending_containment_write('rollback:22222222-2222-4222-8222-222222222222','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),true,'rollback fences writes');
select is(public.reaper_finish_pending_containment('rollback:22222222-2222-4222-8222-222222222222','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','blocked'),true,'unknown rollback permanently blocked');
update private.reaper_pending_containment_runs set created_at='1900-01-01Z' where state='blocked';
select is(public.reaper_reserve_pending_containment('gateway:33333333-3333-4333-8333-333333333333','11111111111111111',repeat('a',64),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'busy','age never expires blocked request');
select is(public.reaper_begin_pending_containment_write('rollback:22222222-2222-4222-8222-222222222222','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),false,'blocked owner cannot continue');
select is(public.reaper_finish_pending_containment('rollback:22222222-2222-4222-8222-222222222222','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','completed','{"discordWrites":0,"dbWrites":0,"staleRecordsCleared":0}'),false,'blocked cannot be cleared by finish');
select is(public.reaper_set_pending_containment_enabled(false),true,'emergency disable closes admission with blocked writer');
select is((select state from private.reaper_pending_containment_runs where request_key='rollback:22222222-2222-4222-8222-222222222222'),'blocked','disable preserves unknown-write fence');
select throws_ok($$select public.reaper_set_pending_containment_enabled(true)$$,'55000','Reconcile active containment before changing policy.','cannot re-enable over blocked fence');
select throws_ok($$select public.reaper_reserve_pending_containment('gateway:33333333-3333-4333-8333-333333333333','*',repeat('a',64),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')$$,'22023','Invalid containment request identity.','Gateway subject mandatory');
select throws_ok($$select public.reaper_reserve_pending_containment('discord:33333333333333333','11111111111111111',repeat('a',64),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')$$,'22023','Invalid containment request identity.','bulk namespace cannot impersonate member');
select throws_ok($$select public.reaper_reserve_pending_containment('gateway:33333333-3333-1333-8333-333333333333','11111111111111111',repeat('a',64),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')$$,'22023','Invalid containment request identity.','only UUIDv4 request IDs');
select throws_ok($$select public.reaper_reserve_pending_containment('gateway:33333333-3333-4333-8333-333333333333','11111111111111111',repeat('x',64),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')$$,'22023','Invalid containment request identity.','hash must be exact hex');
select is((select count(*) from private.reaper_pending_containment_runs),3::bigint,'only actual acquisitions retained');
reset role;
select * from finish();
rollback;
